import { GAME_URL, PHONE, exportedSnapshot, loadFixedBoard, moves } from './game-fixture.ts';

test('finishes the literal board by keyboard without inspecting hidden faces', async ({ page }) => {
  await loadFixedBoard(page);
  await expect(page.locator('.card.closed svg'), 'I14 hidden cards mount no face').toHaveCount(0);
  await expect(page.locator('[data-face], [data-face-id]')).toHaveCount(0);
  for (const pair of EXAMPLE_PAIRS) {
    for (const index of pair) {
      await page.locator('.card').first().focus();
      for (let row = 0; row < Math.floor(index / 4); row += 1)
        await page.keyboard.press('ArrowDown');
      for (let column = 0; column < index % 4; column += 1) await page.keyboard.press('ArrowRight');
      await page.keyboard.press('Enter');
    }
  }
  await expect(page.locator('.card.matched')).toHaveCount(16);
  expect(await moves(page)).toBe(8);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('8');
  expect(await page.locator('.victory').count()).toBe(1);
  const first = await exportedSnapshot(page);
  const second = await exportedSnapshot(page);
  expect(second.elapsedMs).toBe(first.elapsedMs);
});

test('finishes by phone taps with visible 44px targets', async ({ browser }) => {
  const context = await browser.newContext({ viewport: PHONE, isMobile: true, hasTouch: true });
  try {
    const page = await context.newPage();
    await loadFixedBoard(page);
    const bounds = await page.locator('.card').first().boundingBox();
    expect(bounds?.width).toBeGreaterThanOrEqual(44);
    expect(bounds?.height).toBeGreaterThanOrEqual(44);
    for (const pair of EXAMPLE_PAIRS)
      for (const index of pair) await page.locator('.card').nth(index).tap();
    await expect(page.locator('.card.matched')).toHaveCount(16);
    expect(await moves(page)).toBe(8);
  } finally {
    await context.close();
  }
});

test('loads the built file with the network offline and no external requests', async ({
  context,
  page,
}) => {
  const requested: string[] = [];
  page.on('request', (request) => {
    requested.push(request.url());
  });
  await context.setOffline(true);
  await page.goto(GAME_URL);
  await expect(page.locator('.card')).toHaveCount(16);
  await page.locator('.card').first().click();
  await expect(page.locator('.card.revealed')).toHaveCount(1);
  expect(requested).toEqual([GAME_URL]);
});

test('keeps navigation focus at the board edges and leaves the board with Tab', async ({
  page,
}) => {
  await loadFixedBoard(page);
  const cards = page.locator('.card');
  await cards.first().focus();
  await page.keyboard.press('ArrowLeft');
  await expect(cards.first()).toBeFocused();
  await page.keyboard.press('ArrowUp');
  await expect(cards.first()).toBeFocused();
  // A 4x4 row or column takes three presses, so the fourth tests the edge.
  for (let step = 0; step < 4; step += 1) await page.keyboard.press('ArrowRight');
  await expect(cards.nth(3)).toBeFocused();
  for (let step = 0; step < 4; step += 1) await page.keyboard.press('ArrowDown');
  await expect(cards.last()).toBeFocused();
  await expect(page.locator('.card.revealed')).toHaveCount(0);
  await page.keyboard.press('Tab');
  expect(await page.locator('.card:focus').count()).toBe(0);
  expect(await moves(page)).toBe(0);
});
import { expect, test } from './browser-test.ts';
import { finishBoard, loadFixedBoard } from './game-fixture.ts';

test('card transitions use 120ms and a completed game has one 600ms pulse', async ({ page }) => {
  await loadFixedBoard(page);
  const transitions = await page
    .locator('.card')
    .first()
    .evaluate((element) => {
      const style = getComputedStyle(element);
      return { duration: style.transitionDuration, property: style.transitionProperty };
    });
  expect(transitions.duration.split(',').every((duration) => parseFloat(duration) === 0.12)).toBe(
    true,
  );
  expect(transitions.property.split(',').map((value) => value.trim())).toEqual(['border-color']);
  await finishBoard(page);
  const pulse = await page.locator('.victory').evaluate((element) => {
    const style = getComputedStyle(element);
    return { duration: style.animationDuration, iterations: style.animationIterationCount };
  });
  expect(parseFloat(pulse.duration)).toBe(0.6);
  expect(Number(pulse.iterations)).toBe(1);
});

test('reduced motion removes card transitions and completion animation', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await loadFixedBoard(page);
  await finishBoard(page);
  expect(
    await page.locator('.victory').evaluate((element) => getComputedStyle(element).animationName),
  ).toBe('none');
  expect(
    parseFloat(
      await page
        .locator('.card')
        .first()
        .evaluate((element) => getComputedStyle(element).transitionDuration),
    ),
  ).toBe(0);
});
import { expect, test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import {
  GAME_URL,
  exportedSnapshot,
  loadFixedBoard,
  loadTimedBoard,
  finishBoard,
} from './game-fixture.ts';

test('pauses elapsed time and a mismatch while the document is hidden', async ({ page }) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(200);
  // Headless Chromium leaves every tab visible, so control this browser input at the adapter.
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  const before = await exportedSnapshot(page);
  await page.clock.runFor(2000);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(before.elapsedMs);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => false });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(599);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
});

test('continues playing when access to browser storage is denied', async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', {
      get: () => {
        throw new DOMException('Blocked', 'SecurityError');
      },
    });
  });
  await loadFixedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await expect(page.locator('.card.matched')).toHaveCount(2);
});

test('keeps the initial focus and produces no audio during play', async ({ page }) => {
  let audioRequests = 0;
  page.on('request', (request) => {
    if (request.resourceType() === 'media') audioRequests += 1;
  });
  await page.goto(GAME_URL);
  expect(
    await page.locator('button:focus, select:focus, input:focus, textarea:focus').count(),
  ).toBe(0);
  await page.addInitScript(() => {
    for (const key of ['AudioContext', 'webkitAudioContext', 'Audio']) {
      Object.defineProperty(window, key, {
        configurable: true,
        value: class {
          constructor() {
            throw new Error('Unexpected synthesized audio');
          }
        },
      });
    }
    HTMLMediaElement.prototype.play = () => {
      throw new Error('Unexpected media playback');
    };
    speechSynthesis.speak = () => {
      throw new Error('Unexpected synthesized speech');
    };
  });
  await loadFixedBoard(page);
  await finishBoard(page);
  await page.getByRole('button', { name: DealControl.restart, exact: true }).click();
  await expect(page.locator('audio, video')).toHaveCount(0);
  expect(audioRequests).toBe(0);
});
import assert from 'node:assert/strict';
import { test } from 'vitest';
import {
  DEFAULT_SIZE,
  PREFERENCES_KEY,
  PREFERENCES_VERSION,
  readPreferences,
  rememberBest,
  writePreferences,
} from './storage.ts';
import { MOVES_MAX } from '../game.ts';
import { SPEC_VECTOR } from '../game.fixture.ts';
import type { PreferenceStore } from './storage.ts';

function memoryStore(initial = ''): PreferenceStore {
  const entries = new Map([[PREFERENCES_KEY, initial]]);
  return {
    getItem: (key) => entries.get(key) ?? null,
    setItem: (key, value) => {
      entries.set(key, value);
    },
  };
}

test('preferences round trip size and separate minimum moves per size', () => {
  const store = memoryStore();
  const preferences = rememberBest(rememberBest({ size: 6, bestMoves: {} }, 4, 12), 6, 20);
  writePreferences(store, preferences);
  assert.deepEqual(readPreferences(store), preferences, 'R10 scores survive storage round trip');
  assert.equal(rememberBest(preferences, 4, 13), preferences, 'R10 worse score keeps best');
  assert.equal(rememberBest(preferences, 4, 12), preferences);
  assert.equal(rememberBest(preferences, 4, 9).bestMoves['4'], 9, 'R10 better score replaces best');
  assert.equal(preferences.bestMoves['6'], 20, 'R10 size six has its separate best');
});

test('a best at the move cap round trips and a larger saved best is ignored', () => {
  const store = memoryStore();
  const capped = { size: DEFAULT_SIZE, bestMoves: { [DEFAULT_SIZE]: MOVES_MAX } };
  writePreferences(store, capped);
  assert.deepEqual(readPreferences(store), capped);
  assert.equal(rememberBest(capped, DEFAULT_SIZE, MOVES_MAX), capped);
  const larger = {
    schemaVersion: PREFERENCES_VERSION,
    size: DEFAULT_SIZE,
    bestMoves: { [DEFAULT_SIZE]: MOVES_MAX + 1 },
  };
  store.setItem(PREFERENCES_KEY, JSON.stringify(larger));
  assert.deepEqual(readPreferences(store), { size: DEFAULT_SIZE, bestMoves: {} });
});

const INVALID_PREFERENCES = [
  '{',
  'null',
  '{}',
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 5, bestMoves: {} }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: -1 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { 4: 8.5 } }),
  JSON.stringify({ schemaVersion: PREFERENCES_VERSION, size: 6, bestMoves: { '04': 8 } }),
];
for (const [index, text] of INVALID_PREFERENCES.entries()) {
  test(`preferences ignore invalid saved data ${index + 1}`, () => {
    assert.deepEqual(readPreferences(memoryStore(text)), { size: DEFAULT_SIZE, bestMoves: {} });
  });
}

test('storage failures keep play available and never change unrelated keys', () => {
  const denied: PreferenceStore = {
    getItem: () => {
      throw new Error();
    },
    setItem: () => {
      throw new Error();
    },
  };
  assert.equal(DEFAULT_SIZE, SPEC_VECTOR.sizes[0]);
  assert.equal(readPreferences(denied).size, DEFAULT_SIZE);
  assert.doesNotThrow(() => writePreferences(denied, { size: DEFAULT_SIZE, bestMoves: {} }));
  assert.equal(readPreferences(null).size, DEFAULT_SIZE);
  const store = memoryStore();
  const unrelated = 'another-application';
  store.setItem(unrelated, 'kept');
  writePreferences(store, { size: DEFAULT_SIZE, bestMoves: {} });
  assert.equal(store.getItem(unrelated), 'kept');
});

